EAN","JSON","EMAIL"],"fact":"COL-public.lf_global_config.value_type"},{"schema":"lf_ops","table":"pantalla_variantes","constraint":"pantalla_variantes_density_ck","column":"density_mode","familia":"RESPONSIVE","hash":"4fb491303a341d7eac00672271fed1d2","definition":"CHECK ((density_mode = ANY (ARRAY['COMPACT'::text, 'COMFORTABLE'::text, 'SPACIOUS'::text])))","values":["COMPACT","COMFORTABLE","SPACIOUS"],"fact":"COL-lf_ops.pantalla_variantes.density_mode"},{"schema":"lf_ops","table":"pantalla_variantes","constraint":"pantalla_variantes_navigation_ck","column":"navigation_mode","familia":"ROUTING_NAVIGATION","hash":"318701303d8abf7e8d1e8c1196669372","definition":"CHECK ((navigation_mode = ANY (ARRAY['SIDEBAR_EXPANDED'::text, 'SIDEBAR_COLLAPSED'::text, 'MOBILE_DRAWER'::text, 'NO_NAVIGATION'::text])))","values":["SIDEBAR_EXPANDED","SIDEBAR_COLLAPSED","MOBILE_DRAWER","NO_NAVIGATION"],"fact":"COL-lf_ops.pantalla_variantes.navigation_mode"},{"schema":"lf_ops","table":"mensajes_ui","constraint":"mensajes_ui_type_ck","column":"message_type","familia":"UI_MESSAGES","hash":"81402d84abff3bca38b1612776d86e1d","definition":"CHECK ((message_type = ANY (ARRAY['INFO'::text, 'SUCCESS'::text, 'WARNING'::text, 'ERROR'::text, 'EMPTY'::text, 'CONFIRMATION'::text, 'SESSION'::text])))","values":["INFO","SUCCESS","WARNING","ERROR","EMPTY","CONFIRMATION","SESSION"],"fact":"COL-lf_ops.mensajes_ui.message_type"},{"schema":"lf_ops","table":"mensajes_ui","constraint":"mensajes_ui_visibility_ck","column":"visibility_scope","familia":"UI_MESSAGES","hash":"3ddcbae0caeb54549b17a92c10f6c2cb","definition":"CHECK ((visibility_scope = ANY (ARRAY['USER'::text, 'DEVELOPER'::text, 'BOTH'::text])))","values":["USER","DEVELOPER","BOTH"],"fact":"COL-lf_ops.mensajes_ui.visibility_scope"},{"schema":"lf_ops","table":"errores_catalogo","constraint":"errores_catalogo_severity_ck","column":"severity","familia":"ERRORS","hash":"2ba46a2b62d2357a8bb963f8fb53cfba","definition":"CHECK ((severity = ANY (ARRAY['INFO'::text, 'LOW'::text, 'MEDIUM'::text, 'HIGH'::text, 'CRITICAL'::text])))","values":["INFO","LOW","MEDIUM","HIGH","CRITICAL"],"fact":"COL-lf_ops.errores_catalogo.severity"},{"schema":"lf_ops","table":"errores_catalogo","constraint":"errores_catalogo_log_level_ck","column":"log_level","familia":"ERRORS","hash":"31dfe4628a191a52e6eb532114b284d3","definition":"CHECK ((log_level = ANY (ARRAY['DEBUG'::text, 'INFO'::text, 'WARN'::text, 'ERROR'::text, 'FATAL'::text])))","values":["DEBUG","INFO","WARN","ERROR","FATAL"],"fact":"COL-lf_ops.errores_catalogo.log_level"},{"schema":"lf_ops","table":"rutas","constraint":"rutas_type_ck","column":"route_type","familia":"ROUTING_NAVIGATION","hash":"bda38dcbcb3222c5164975f167821453","definition":"CHECK ((route_type = ANY (ARRAY['INTERNAL'::text, 'CONTEXTUAL'::text, 'EXTERNAL'::text, 'REDIRECT'::text])))","values":["INTERNAL","CONTEXTUAL","EXTERNAL","REDIRECT"],"fact":"COL-lf_ops.rutas.route_type"},{"schema":"lf_ops","table":"politicas_timeout","constraint":"politicas_timeout_backoff_ck","column":"backoff_strategy","familia":"TIMEOUT_RETRY","hash":"4fd4f26d7eddf018c12528ea045ec068","definition":"CHECK ((backoff_strategy = ANY (ARRAY['NONE'::text, 'FIXED'::text, 'LINEAR'::text, 'EXPONENTIAL'::text])))","values":["NONE","FIXED","LINEAR","EXPONENTIAL"],"fact":"COL-lf_ops.politicas_timeout.backoff_strategy"},{"schema":"lf_ops","table":"pantalla_elementos","constraint":"pantalla_elementos_semantic_binding_status_check","column":"semantic_binding_status","familia":"ACCESSIBILITY","hash":"34f9bca1ddb5d8cfc3b9f08c8579a593","definition":"CHECK ((semantic_binding_status = ANY (ARRAY['RESOLVED_ID'::text, 'PENDING_SEMANTIC_COMPONENT'::text, 'MISSING'::text, 'NOT_APPLICABLE'::text])))","values":["RESOLVED_ID","PENDING_SEMANTIC_COMPONENT","MISSING","NOT_APPLICABLE"],"fact":"COL-lf_ops.pantalla_elementos.semantic_binding_status"},{"schema":"lf_ops","table":"pantalla_artefactos","constraint":"pantalla_artefactos_access_level_ck","column":"access_level","familia":"VISUAL_EVIDENCE","hash":"f0dab7457d2b504642482f03a42a21df","definition":"CHECK ((access_level = ANY (ARRAY['PRIVATE'::text, 'AUTHENTICATED'::text, 'PUBLIC'::text])))","values":["PRIVATE","AUTHENTICATED","PUBLIC"],"fact":"COL-lf_ops.pantalla_artefactos.access_level"},{"schema":"lf_ops","table":"pantalla_artefactos","constraint":"pantalla_artefactos_storage_provider_ck","column":"storage_provider","familia":"VISUAL_EVIDENCE","hash":"e56fcc9bc064a07d5970b66abb09736d","definition":"CHECK ((storage_provider = ANY (ARRAY['SUPABASE_STORAGE'::text, 'GOOGLE_DRIVE'::text])))","values":["SUPABASE_STORAGE","GOOGLE_DRIVE"],"fact":"COL-lf_ops.pantalla_artefactos.storage_provider"},{"schema":"lf_ops","table":"analytics_eventos_definicion","constraint":"analytics_eventos_status_ck","column":"status","familia":"PRIVACY_PII","hash":"61b045ff16ca698f28f552a75569eb94","definition":"CHECK ((status = ANY (ARRAY['CANDIDATO'::text, 'EN_REVISION'::text, 'VIGENTE'::text, 'INACTIVO'::text, 'ARCHIVADO'::text])))","values":["CANDIDATO","EN_REVISION","VIGENTE","INACTIVO","ARCHIVADO"],"fact":"COL-lf_ops.analytics_eventos_definicion.status"}]}$f0json$::jsonb);

DO $pre$
DECLARE a jsonb; f jsonb; p jsonb; e jsonb; current_def text; current_type text; match_n integer;
BEGIN
 SELECT payload INTO a FROM f0_lote_fuente;
 IF jsonb_array_length(a->'families')<>36 OR jsonb_array_length(a->'enums')<>25
 OR (SELECT count(*) FROM lf_ops.nucleo_familias)<>64
 OR (SELECT count(*) FROM lf_ops.nucleo_familia_vocabulario) < 300
 OR to_regclass('lf_ops.f0_valores_vocabulario_v1') IS NOT NULL
 THEN RAISE EXCEPTION 'F0_VOCAB_PRESTATE_DRIFT'; END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(a->'families') LOOP
   IF NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_familias z
        WHERE z.codigo=f->>'familia' AND z.descripcion=f->>'definicion' AND z.tipo=f->>'tipo' AND z.estado=f->>'estado_familia')
   OR EXISTS(SELECT 1 FROM lf_ops.nucleo_familia_vocabulario z WHERE z.familia=f->>'familia')
   THEN RAISE EXCEPTION 'F0_VOCAB_FAMILY_SOURCE_DRIFT: %',f->>'familia'; END IF;
   FOR p IN SELECT value FROM jsonb_array_elements(f->'physical') LOOP
     SELECT c.data_type INTO current_type FROM information_schema.columns c
       WHERE c.table_schema=split_part(p->>'source_table','.',1)
       AND c.table_name=split_part(p->>'source_table','.',2)
       AND c.column_name=p->>'source_column';
     IF current_type IS DISTINCT FROM p->>'source_data_type'
     THEN RAISE EXCEPTION 'F0_VOCAB_COLUMN_SOURCE_DRIFT: % %, wanted %',p->>'fact',current_type,p->>'source_data_type'; END IF;
   END LOOP;
 END LOOP;
 FOR e IN SELECT value FROM jsonb_array_elements(a->'enums') LOOP
   SELECT pg_get_constraintdef(c.oid) INTO current_def FROM pg_constraint c
    JOIN pg_class t ON t.oid=c.conrelid
    JOIN pg_namespace n ON n.oid=t.relnamespace
    WHERE n.nspname=e->>'schema' AND t.relname=e->>'table'
      AND c.conname=e->>'constraint';
   IF current_def IS DISTINCT FROM e->>'definition' OR md5(current_def) IS DISTINCT FROM e->>'hash'
   THEN RAISE EXCEPTION 'F0_ENUM_CONSTRAINT_SOURCE_DRIFT %',e->>'constraint'; END IF;
 END LOOP;
END $pre$;

CREATE TABLE lf_ops.f0_valores_vocabulario_v1 (
 hecho text NOT NULL REFERENCES lf_ops.nucleo_hechos(codigo) ON DELETE RESTRICT,
 valor text NOT NULL,
 fuente_esquema text NOT NULL,
 fuente_tabla text NOT NULL,
 fuente_columna text NOT NULL,
 fuente_constraint text NOT NULL,
 fuente_def_md5 text NOT NULL CHECK(fuente_def_md5 ~ '^[0-9a-f]{32}$'),
 origen text NOT NULL DEFAULT 'DB_CHECK_REAL' CHECK(origen='DB_CHECK_REAL'),
 created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(hecho,valor),
 CONSTRAINT f0_enum_valor_not_empty CHECK(length(btrim(valor))>0),
 CONSTRAINT f0_enum_source_match CHECK (hecho='COL-'||fuente_esquema||'.'||fuente_tabla||'.'||fuente_columna)
);
ALTER TABLE lf_ops.f0_valores_vocabulario_v1 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE lf_ops.f0_valores_vocabulario_v1 FROM PUBLIC,anon,authenticated;
GRANT SELECT ON TABLE lf_ops.f0_valores_vocabulario_v1 TO service_role;
CREATE FUNCTION lf_ops.f0_valor_permitido_v1(p_hecho text,p_valor text)
 RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER
 SET search_path TO 'pg_catalog','lf_ops'
 AS $fn$
 SELECT EXISTS(SELECT 1 FROM lf_ops.f0_valores_vocabulario_v1 v
                 WHERE v.hecho=p_hecho AND v.valor=p_valor)
 $fn$;
REVOKE ALL ON FUNCTION lf_ops.f0_valor_permitido_v1(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION lf_ops.f0_valor_permitido_v1(text,text) TO service_role;

-- Insertar una sola vez cada columna física existente y derivar su tipo de information_schema en v_nucleo_vocabulario.
INSERT INTO lf_ops.nucleo_hechos(codigo,tabla_ref,columna_ref)
SELECT DISTINCT p->>'fact', p->>'source_table',p->>'source_column'
FROM f0_lote_fuente i,
 jsonb_array_elements(i.payload->'families') AS f,
 jsonb_array_elements(f.value->'physical') AS p
WHERE NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_hechos h WHERE h.codigo=p->>'fact');

-- Hechos puramente lógicos: de la definición canónica de cada familia, sin binding operativo ni valores inventados.
INSERT INTO lf_ops.nucleo_hechos(codigo,tipo_dato,unidad,descripcion)
SELECT f.value->'logical'->>'fact', f.value->'logical'->>'tipo_dato',
 f.value->'logical'->>'unidad',f.value->'logical'->>'descripcion'
FROM f0_lote_fuente i,jsonb_array_elements(i.payload->'families') AS f
WHERE f.value->'logical' IS NOT NULL AND jsonb_typeof(f.value->'logical')='object';

INSERT INTO lf_ops.nucleo_familia_vocabulario(familia,hecho,origen)
SELECT f.value->>'familia',p.value->>'fact','COLUMNA_NEGOCIO'
 FROM f0_lote_fuente i,jsonb_array_elements(i.payload->'families') AS f,
 jsonb_array_elements(f.value->'physical') AS p
UNION ALL
SELECT f.value->>'familia',f.value->'logical'->>'fact','CURADO'
 FROM f0_lote_fuente i,jsonb_array_elements(i.payload->'families') AS f
 WHERE jsonb_typeof(f.value->'logical')='object';

INSERT INTO lf_ops.f0_valores_vocabulario_v1(
 hecho,valor,fuente_esquema,fuente_tabla,fuente_columna,fuente_constraint,fuente_def_md5,origen)
SELECT e.value->>'fact',v.value,e.value->>'schema',e.value->>'table',
       e.value->>'column',e.value->>'constraint',e.value->>'hash','DB_CHECK_REAL'
 FROM f0_lote_fuente i,jsonb_array_elements(i.payload->'enums') AS e,
 jsonb_array_elements_text(e.value->'values') AS v;

DO $checks$
DECLARE a jsonb; f jsonb; e jsonb; found bigint; facts_before bigint; lf_before text; saly_before text; v text; altered boolean;
BEGIN
 SELECT payload INTO a FROM f0_lote_fuente;
 IF (SELECT count(*) FROM lf_ops.nucleo_familias f WHERE NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_familia_vocabulario v WHERE v.familia=f.codigo))<>0
 THEN RAISE EXCEPTION 'F0_VOCAB_NOT_64_OF_64'; END IF;
 IF (SELECT count(*) FROM lf_ops.f0_valores_vocabulario_v1)<>94
 OR (SELECT count(DISTINCT fuente_constraint) FROM lf_ops.f0_valores_vocabulario_v1)<>25
 THEN RAISE EXCEPTION 'F0_ENUM_TOTAL_BAD'; END IF;
 IF (SELECT count(*) FROM lf_ops.nucleo_hechos WHERE codigo LIKE 'f0_%')<>10
 THEN RAISE EXCEPTION 'F0_LOGICAL_COUNT_BAD'; END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(a->'families') LOOP
   SELECT count(*) INTO found FROM lf_ops.nucleo_familia_vocabulario z WHERE z.familia=f->>'familia';
   IF found<>jsonb_array_length(f->'physical')+CASE WHEN f->'logical' IS NULL THEN 0 ELSE 1 END
   THEN RAISE EXCEPTION 'F0_VOCAB_MAPPING_MISMATCH % %',f->>'familia',found; END IF;
 END LOOP;
 FOR e IN SELECT value FROM jsonb_array_elements(a->'enums') LOOP
   SELECT count(*) INTO found FROM lf_ops.f0_valores_vocabulario_v1 x WHERE x.hecho=e->>'fact';
   IF found<>jsonb_array_length(e->'values') THEN RAISE EXCEPTION 'F0_ENUM_CARDINALITY % %',e->>'fact',found; END IF;
   FOR v IN SELECT value FROM jsonb_array_elements_text(e->'values') LOOP
     IF lf_ops.f0_valor_permitido_v1(e->>'fact',v) IS NOT TRUE
     THEN RAISE EXCEPTION 'F0_ENUM_TRUE_FAIL % %',e->>'fact',v; END IF;
   END LOOP;
   IF lf_ops.f0_valor_permitido_v1(e->>'fact','__VALOR_NO_REGISTRADO_F0__') IS DISTINCT FROM false
   THEN RAISE EXCEPTION 'F0_ENUM_UNKNOWN_ALLOWED %',e->>'fact'; END IF;
 END LOOP;
 -- Negativo: FK inválida se rechaza.
 BEGIN
   INSERT INTO lf_ops.f0_valores_vocabulario_v1
    (hecho,valor,fuente_esquema,fuente_tabla,fuente_columna,fuente_constraint,fuente_def_md5)
   VALUES ('COL-zz_fuente_ausente.tabla.valor','X','zz_fuente_ausente','tabla','valor','x',repeat('0',32));
   RAISE EXCEPTION 'F0_ENUM_INVALID_FK_ACCEPTED';
 EXCEPTION WHEN foreign_key_violation THEN NULL; END;
 -- Negativo: origen falso no se registra.
 BEGIN
   INSERT INTO lf_ops.f0_valores_vocabulario_v1
    (hecho,valor,fuente_esquema,fuente_tabla,fuente_columna,fuente_constraint,fuente_def_md5,origen)
   VALUES ('COL-lf_ops.nucleo_nodos.nivel','FRAUD','lf_ops','nucleo_nodos','nivel','nucleo_nodos_nivel_valido',repeat('0',32),'INVENTADO');
   RAISE EXCEPTION 'F0_ENUM_FAKE_PROVENANCE_ACCEPTED';
 EXCEPTION WHEN check_violation THEN NULL; END;
 -- Negativo: una columna no puede presentarse como otra.
 BEGIN
   INSERT INTO lf_ops.f0_valores_vocabulario_v1
    (hecho,valor,fuente_esquema,fuente_tabla,fuente_columna,fuente_constraint,fuente_def_md5)
   VALUES ('COL-lf_ops.nucleo_nodos.nivel','FRAUD','lf_ops','nucleo_nodos','padre','nucleo_nodos_nivel_valido',repeat('0',32));
   RAISE EXCEPTION 'F0_ENUM_SOURCE_BINDING_ACCEPTED';
 EXCEPTION WHEN check_violation THEN NULL; END;
 -- Negativo: duplicar valor no crea una segunda fila.
 BEGIN
   INSERT INTO lf_ops.f0_valores_vocabulario_v1
    (hecho,valor,fuente_esquema,fuente_tabla,fuente_columna,fuente_constraint,fuente_def_md5)
   SELECT hecho,valor,fuente_esquema,fuente_tabla,fuente_columna,fuente_constraint,fuente_def_md5
     FROM lf_ops.f0_valores_vocabulario_v1 LIMIT 1;
   RAISE EXCEPTION 'F0_ENUM_DUPLICATE_ACCEPTED';
 EXCEPTION WHEN unique_violation THEN NULL; END;
 -- Negativo: insertar una relación duplicada no reescribe la existente.
 BEGIN
   INSERT INTO lf_ops.nucleo_familia_vocabulario(familia,hecho,origen)
     SELECT familia,hecho,origen FROM lf_ops.nucleo_familia_vocabulario
       WHERE familia='ACCESSIBILITY' LIMIT 1;
   RAISE EXCEPTION 'F0_FAMILY_DUPLICATE_ACCEPTED';
 EXCEPTION WHEN unique_violation THEN NULL; END;
 IF EXISTS(SELECT 1 FROM saly.nucleo_hechos WHERE codigo LIKE 'f0_%')
 OR EXISTS(SELECT 1 FROM lf_ops.nucleo_reglas WHERE codigo LIKE 'F0-%')
 OR EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE origen->>'ref' LIKE 'F0%')
 THEN RAISE EXCEPTION 'F0_CROSS_DOMAIN_WRITE_DETECTED'; END IF;
 IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid='lf_ops.f0_valores_vocabulario_v1'::regclass)
 THEN RAISE EXCEPTION 'F0_ENUM_RLS_MISSING'; END IF;
 RAISE NOTICE 'F0_VOCAB_PASS 36/36 familias; 55 hechos físicos únicos, 10 lógicos sin binding; 67 enlaces; 25 CHECK, 94 valores; 6 negativas, no publicación';
END $checks$;
COMMIT;
